static bool Mt2009PlusRareDropOff(int kind, bool stone)
{
	static const char* const s_aFlags[MT2009_PLUS_RARE_DROP_NONE][2] =
	{
		{ "m2_sm_boss_off", "m2_sm_metin_off" },
		{ "m2_sash_boss_off", "m2_sash_metin_off" },
		{ "m2_cor_boss_off", "m2_cor_metin_off" },
	};
	if (kind < 0 || kind >= MT2009_PLUS_RARE_DROP_NONE)
		return false;
	return quest::CQuestManager::instance().GetEventFlag(s_aFlags[kind][stone ? 1 : 0]) != 0;
}

// The switch a drop table's item falls under: a Kupon SM (80014-80018), a Cor Draconis
// (50252, 50255-50260) or a sash (any COSTUME_ACCE).
static int Mt2009PlusRareDropKind(DWORD vnum)
{
	if (vnum >= 80014 && vnum <= 80018)
		return MT2009_PLUS_RARE_DROP_SM;
	if (vnum == 50252 || (vnum >= 50255 && vnum <= 50260))
		return MT2009_PLUS_RARE_DROP_COR;
	const TItemTable* table = ITEM_MANAGER::instance().GetTable(vnum);
	if (table && table->bType == ITEM_COSTUME && table->bSubType == COSTUME_ACCE)
		return MT2009_PLUS_RARE_DROP_SASH;
	return MT2009_PLUS_RARE_DROP_NONE;
}

// A built-in drop table row's item of a Metin or a boss whose switch is off (an ordinary
// monster's rows: never).
static bool Mt2009PlusRareTableRowOff(DWORD vnum, bool stone, bool boss)
{
	if (!stone && !boss)
		return false;
	return Mt2009PlusRareDropOff(Mt2009PlusRareDropKind(vnum), stone);
}

